internal struct POINT
{
    public int x;
    public int y;
    public POINT(int x, int y) { this.x = x; this.y = y; }
    public static implicit operator Point(POINT p) => new(p.x, p.y);
    public static implicit operator POINT(Point p) => new(p.X, p.Y);
}

