internal struct RECTL
{
    public int left;
    public int top;
    public int right;
    public int bottom;
    public RECTL(int left, int top, int right, int bottom)
    {
        this.left = left;
        this.top = top;
        this.right = right;
        this.bottom = bottom;
    }
    public static implicit operator Rectangle(RECTL r) => Rectangle.FromLTRB(r.left, r.top, r.right, r.bottom);
    public static implicit operator RECTL(Rectangle r) => new(r.Left, r.Top, r.Right, r.Bottom);
}

internal partial struct RECT
{
    public int left;
    public int top;
    public int right;
    public int bottom;

    public RECT(int left, int top, int right, int bottom)
    {
        this.left = left;
        this.top = top;
        this.right = right;
        this.bottom = bottom;
    }

    public static implicit operator Rectangle(RECT r) => Rectangle.FromLTRB(r.left, r.top, r.right, r.bottom);
    public static implicit operator RECT(Rectangle r) => new(r.Left, r.Top, r.Right, r.Bottom);
    public int X => left;
    public int Y => top;
    public int Width => right - left;
    public int Height => bottom - top;
    public Point Position => new(left, top);
    public Size Size => new(Width, Height);
}

